export function initReadingUI(root,path,elements,selfLayers,selfElements,catalogue=[]){
 if(!path)return ()=>{};
 const shell=root.querySelector('.page-shell');if(!shell)return ()=>{};
 root.querySelectorAll('.overview-group').forEach(group=>{const box=group.firstElementChild;if(box.querySelector('a'))return;const h=box.querySelector('h2'),p=box.querySelector('p');if(!h||!p)return;const ids={'本源':'origin','变化':'change','创造':'creation','接纳自己':'acceptance','创造自己':'becoming','王之三勇':'courage','王之三力':'powers','王之三道':'ways'};const id=ids[h.textContent];if(!id)return;const a=document.createElement('a');a.className='overview-knowing-link';a.href=id==='becoming'?'#/becoming':'#/map?focus='+id;h.before(a);a.append(h,p);});
 const element=elements.find(e=>path==='becoming/'+e.id),self=selfElements.find(e=>path==='knowing/'+e.id);
 if(element){const nav=document.createElement('nav');nav.className='reading-position';nav.setAttribute('aria-label','在三层九项中的位置');nav.innerHTML=['意识层','模板层','实相层'].map((name,i)=>`<div><span>${name}</span>${elements.slice(i*3,i*3+3).map(e=>`<a href="#/becoming/${e.id}" ${e.id===element.id?'aria-current="page"':''}>${e.name}</a>`).join('')}</div>`).join('');shell.querySelector('header').after(nav);}
 if(self&&!shell.querySelector('.kn-compact')){const nav=document.createElement('nav');nav.className='reading-position';nav.setAttribute('aria-label','在三个我中的位置');nav.innerHTML=selfLayers.map(l=>`<div><a href="#/knowing/${l.id}">${l.name}</a>${l.parts.map(id=>{const e=selfElements.find(e=>e.id===id);return `<a href="#/knowing/${id}" ${id===self.id?'aria-current="page"':''}>${e.name}</a>`;}).join('')}</div>`).join('');shell.querySelector('header').after(nav);}
 const original=shell.querySelector('.be-element-toc,.action-toc,.article-toc');let items=[];
 if(original){items=[...original.querySelectorAll('[data-element-anchor],[data-scroll]')].map(b=>({id:b.dataset.elementAnchor||b.dataset.scroll,label:document.getElementById(b.dataset.elementAnchor||b.dataset.scroll)?.querySelector('h2,h3')?.textContent.trim()||b.textContent.replace(/[↘↗]/g,'').replace(/\s+/g,' ').trim()})).filter(x=>document.getElementById(x.id));}
 else if(path.startsWith('knowing/')){items=[...shell.querySelectorAll('.kn-section')].map((s,i)=>{s.id||='reading-section-'+i;return {id:s.id,label:s.querySelector('.eyebrow')?.textContent||s.querySelector('h2')?.textContent||'三个面向'};});}
 let onScroll=()=>{},frame=0,details;
 if(items.length>1){details=document.createElement('details');details.className='reading-contents';if(original?.id)details.id=original.id;details.innerHTML='<summary><span>本页目录</span><small class="reading-current"></small></summary><nav aria-label="本页章节">'+items.map((x,i)=>`<button type="button" data-reading-target="${i}">${x.label}</button>`).join('')+'</nav>';
 if(original){if(original.classList.contains('article-toc')){original.closest('.article-layout').before(details);original.remove();shell.classList.add('reading-single-column');}else original.replaceWith(details);}else shell.querySelector('.kn-compact,.reading-position,header').after(details);
 const buttons=[...details.querySelectorAll('button')],targets=items.map(x=>document.getElementById(x.id));
 buttons.forEach((b,i)=>b.onclick=()=>{details.open=false;const t=targets[i];if(t.matches('details'))t.open=true;t.querySelectorAll('details').forEach(d=>{if(t.id.endsWith('sources'))d.open=true;});t.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});t.tabIndex=-1;t.focus({preventScroll:true});});
 const update=()=>{frame=0;let active=0;targets.forEach((t,i)=>{if(t.getBoundingClientRect().top<Math.max(190,innerHeight*.35))active=i;});buttons.forEach((b,i)=>i===active?b.setAttribute('aria-current','location'):b.removeAttribute('aria-current'));details.querySelector('.reading-current').textContent=items[active].label;};onScroll=()=>{if(!frame)frame=requestAnimationFrame(update);};window.addEventListener('scroll',onScroll,{passive:true});update();
 details.addEventListener('keydown',e=>{if(e.key==='Escape'){details.open=false;details.querySelector('summary').focus();}});
 }
 const oldFooter=shell.querySelector('.be-element-footer,.kn-next');
 let next,back;
 if(element){const i=elements.indexOf(element);next=i<8?['becoming/'+elements[i+1].id,'下一项：'+elements[i+1].name]:['becoming/mechanism','进入创造的循环'];back=['becoming','返回创造自己'];}
 else if(self){const layer=selfLayers.find(l=>l.id===self.layer),i=layer.parts.indexOf(self.id);next=i<2?['knowing/'+layer.parts[i+1],'继续阅读：'+selfElements.find(e=>e.id===layer.parts[i+1]).name]:['knowing/'+layer.id,'回看'+layer.name];back=['knowing','返回完整结构'];}
 else if(path.startsWith('knowing/')){const i=selfLayers.findIndex(l=>path==='knowing/'+l.id);if(i>=0){next=i<2?['knowing/'+selfLayers[i+1].id,'继续阅读：'+selfLayers[i+1].name]:['acceptance','走向接纳自己'];back=['knowing','返回完整结构'];}}
 if(!next&&(path.startsWith('concept/')||path==='layout')){const id=path==='layout'?'layout':path.split('/')[1],node=catalogue.find(n=>n.id===id);if(node){const siblings=catalogue.filter(n=>node.parent?n.parent===node.parent:n.groupId===node.groupId&&n.path===node.path),i=siblings.findIndex(n=>n.id===id),n=siblings[i+1];next=n?[n.id==='layout'?'layout':'concept/'+n.id,'继续阅读：'+n.name]:[node.path||'wang','回到'+({tian:'天道',ren:'人道',wang:'王道'}[node.path]||'王道')];back=['map','返回三道全图'];}}
 if(['concept/cognitive','concept/emotional','concept/existential'].includes(path)){back=['acceptance','返回接纳自己'];if(path==='concept/existential')next=['becoming','走向创造自己'];}
 if(next&&!shell.classList.contains('wang-page')){const nav=document.createElement('nav');nav.className='reading-next';nav.setAttribute('aria-label','继续阅读');nav.innerHTML=`<a class="reading-next-primary" href="#/${next[0]}">${next[1]} <span aria-hidden="true">→</span></a><a class="reading-next-back" href="#/${back[0]}">${back[1]}</a>`;oldFooter?oldFooter.replaceWith(nav):shell.append(nav);shell.querySelectorAll('.intention-back').forEach(a=>a.remove());}
 return ()=>{window.removeEventListener('scroll',onScroll);cancelAnimationFrame(frame);};
}
